def by_video():
    """يُرجِع قاموسًا: رقم الفيديو ⇐ قائمة أسئلته."""
    out = {}
    for row in QS:
        out.setdefault(row[0], []).append(row)
    return out


def topics():
    seen = []
    for r in QS:
        if r[1] not in seen:
            seen.append(r[1])
    return seen
